    lastUsedAt: apiKeys.lastUsedAt,
    createdAt: apiKeys.createdAt,
  }).from(apiKeys).where(eq(apiKeys.userId, userId));
}

export async function validateApiKey(key: string) {
  const db = await getDb();
  if (!db) return null;

  const hash = hashApiKey(key);
  const result = await db.select()
    .from(apiKeys)
    .where(and(eq(apiKeys.keyHash, hash), eq(apiKeys.isActive, true)))
    .limit(1);

  if (result.length === 0) return null;

  // Update last used
  await db.update(apiKeys)
    .set({ lastUsedAt: new Date() })
    .where(eq(apiKeys.id, result[0].id));

  return result[0];
}

export async function deleteApiKey(userId: number, keyId: number) {
  const db = await getDb();
  if (!db) return false;

  await db.delete(apiKeys)
    .where(and(eq(apiKeys.id, keyId), eq(apiKeys.userId, userId)));
  return true;
}

export async function regenerateApiKey(userId: number, keyId: number) {
  const db = await getDb();
  if (!db) throw new Error("Database not available");

  const { key, hash, prefix } = generateApiKey();

  await db.update(apiKeys)
    .set({ keyHash: hash, keyPrefix: prefix })
    .where(and(eq(apiKeys.id, keyId), eq(apiKeys.userId, userId)));

  return { key, prefix };
}

