// ============ Leads Functions ============

/**
 * Calculate lead score based on scan results
 * Higher escalation risk + higher value at risk = higher score
 */
function calculateLeadScore(data: {
  escalationRisk?: number;
  churnProbability?: number;
  valueAtRisk?: number;
}): { score: number; tier: 'cold' | 'warm' | 'hot' | 'qualified' } {
  let score = 0;

  // Escalation risk contributes 0-40 points
  if (data.escalationRisk) {
    score += Math.round(data.escalationRisk * 0.4);
  }

  // Churn probability contributes 0-30 points
  if (data.churnProbability) {
    score += Math.round(data.churnProbability * 0.3);
  }

  // Value at risk contributes 0-30 points (capped at $10k)
  if (data.valueAtRisk) {
    const valueScore = Math.min(data.valueAtRisk / 10000, 1) * 30;
    score += Math.round(valueScore);
  }

  // Determine tier based on score
  let tier: 'cold' | 'warm' | 'hot' | 'qualified';
  if (score >= 70) {
    tier = 'qualified';
  } else if (score >= 50) {
    tier = 'hot';
  } else if (score >= 30) {
    tier = 'warm';
  } else {
    tier = 'cold';
  }

  return { score, tier };
}

export async function createLead(data: Omit<InsertLead, 'leadScore' | 'leadTier'>): Promise<Lead | null> {
  const db = await getDb();
  if (!db) return null;

  try {
    // Calculate lead score
    const { score, tier } = calculateLeadScore({
      escalationRisk: data.escalationRisk ?? undefined,
      churnProbability: data.churnProbability ?? undefined,
      valueAtRisk: data.valueAtRisk ?? undefined,
    });

    const leadData: InsertLead = {
      ...data,
      leadScore: score,
      leadTier: tier,
    };

    const [insertedLead] = await db.insert(leads).values(leadData).returning({ id: leads.id });
    const insertId = insertedLead?.id;

    if (insertId) {
      // Log the lead capture activity
      await logLeadActivity(insertId, 'email_captured', {
        source: data.sourcePage,
        utmSource: data.utmSource,
        leadScore: score,
        leadTier: tier,
      });

      // Fetch and return the created lead
      const created = await db.select().from(leads).where(eq(leads.id, insertId)).limit(1);
      return created[0] || null;
    }

    return null;
  } catch (error) {
    dbLog.error({ err: error instanceof Error ? error : new Error(String(error)) }, '[Leads] Error creating lead');
    return null;
  }
}

