// ============ Failure Mode Functions (Top Failure Modes Report) ============

export async function recordFailureMode(
  predictedState: string,
  actualState: string,
  signals?: string[],
  reason?: string
): Promise<void> {
  const db = await getDb();
  if (!db) return;

  const confusionPair = `${predictedState}->${actualState}`;

  try {
    // Check if this confusion pair exists
    const existing = await db.select()
      .from(failureModes)
      .where(eq(failureModes.confusionPair, confusionPair))
      .limit(1);

    if (existing.length > 0) {
      // Update existing
      const existingSignals = existing[0].commonSignals 
        ? JSON.parse(existing[0].commonSignals) as string[]
        : [];
      const existingReasons = existing[0].commonReasons
        ? JSON.parse(existing[0].commonReasons) as string[]
        : [];

      // Merge signals and reasons
      const mergedSignals = [...new Set([...existingSignals, ...(signals || [])])].slice(0, 10);
      const mergedReasons = reason 
        ? [...new Set([...existingReasons, reason])].slice(0, 10)
        : existingReasons;

      await db.update(failureModes)
        .set({
          occurrenceCount: sql`${failureModes.occurrenceCount} + 1`,
          lastOccurrence: new Date(),
          commonSignals: JSON.stringify(mergedSignals),
          commonReasons: JSON.stringify(mergedReasons),
        })
        .where(eq(failureModes.confusionPair, confusionPair));
    } else {
      // Create new
      await db.insert(failureModes).values({
        confusionPair,
        predictedState,
        actualState,
        occurrenceCount: 1,
        commonSignals: signals ? JSON.stringify(signals) : null,
        commonReasons: reason ? JSON.stringify([reason]) : null,
        status: 'new',
      });
    }
  } catch (error) {
    dbLog.error({ err: error instanceof Error ? error : new Error(String(error)) }, '[FailureMode] Error recording');
  }
}

