    return null;
  }
}

/**
 * Update governance settings with partial values.
 * Used by auto-apply config and control tower.
 */
export async function updateGovernanceSettings(params: Partial<InsertGovernanceSettings> & { updatedBy?: string }): Promise<GovernanceSettings | null> {
  const db = await getDb();
  if (!db) return null;
  try {
    const existing = await getGovernanceSettings();
    if (!existing) return null;

    const updateData: Record<string, unknown> = {};
    if (params.activeProfile !== undefined) updateData.activeProfile = params.activeProfile;
    if (params.profileLocked !== undefined) updateData.profileLocked = params.profileLocked;
    if ((params as unknown as Record<string, unknown>).autoApplyMode !== undefined) updateData.autoApplyMode = (params as unknown as Record<string, unknown>).autoApplyMode;
    if ((params as unknown as Record<string, unknown>).autoApplyMaxSeverity !== undefined) updateData.autoApplyMaxSeverity = (params as unknown as Record<string, unknown>).autoApplyMaxSeverity;
    if (params.updatedBy) updateData.lastUpdatedBy = params.updatedBy;

    if (Object.keys(updateData).length > 0) {
      await db.update(governanceSettings).set(updateData).where(eq(governanceSettings.id, existing.id));
    }
    return getGovernanceSettings();
  } catch (error) {
    dbLog.error({ err: error instanceof Error ? error : new Error(String(error)) }, '[GovernanceSettings] Error updating settings');
    return null;
  }
}

/**
 * Update the active enforcement profile.
 * Returns false if profile is locked (unless breakGlass is true).
 */
export async function updateActiveProfile(params: {
  profile: 'Standard' | 'Enterprise' | 'Regulated' | 'High-sensitivity';
  actor: string;
  actorId?: number;
  reason?: string;
  breakGlass?: boolean;
}): Promise<{ success: boolean; error?: string; previousProfile?: string }> {
  const db = await getDb();
  if (!db) return { success: false, error: 'Database not available' };

  try {
    const settings = await getGovernanceSettings();
    if (!settings) {
      await initGovernanceSettings();
      return updateActiveProfile(params);
    }

    // Check lock
    if (settings.profileLocked && !params.breakGlass) {
      return { 
        success: false, 
        error: `Profile is locked by ${settings.lockedBy || 'unknown'}. Use break-glass override to change.`,
        previousProfile: settings.activeProfile 
      };
    }

    const previousProfile = settings.activeProfile;

    // Update settings
    await db.update(governanceSettings).set({
      activeProfile: params.profile,
      lastUpdatedBy: params.actor,
      lastUpdatedAt: new Date(),
    }).where(eq(governanceSettings.id, settings.id));

    // Write audit log
    await db.insert(governanceAuditLog).values({
      action: params.breakGlass ? 'break_glass' : 'profile_change',
      actor: params.actor,
      actorId: params.actorId,
      previousProfile,
      newProfile: params.profile,
      reason: params.reason || (params.breakGlass ? `Break-glass override: ${previousProfile} → ${params.profile}` : undefined),
    });

    dbLog.info({ previousProfile, newProfile: params.profile, actor: params.actor, breakGlass: params.breakGlass }, '[GovernanceSettings] Profile changed');

    return { success: true, previousProfile };
  } catch (error) {
    dbLog.error({ err: error instanceof Error ? error : new Error(String(error)) }, '[GovernanceSettings] Error updating profile');
    return { success: false, error: String(error) };
  }
}

/**
 * Lock the enforcement profile to prevent changes without break-glass.
 */
export async function lockProfile(params: {
  actor: string;
  actorId?: number;
  reason: string;
}): Promise<{ success: boolean; error?: string }> {
  const db = await getDb();
  if (!db) return { success: false, error: 'Database not available' };

  try {
    const settings = await getGovernanceSettings();
    if (!settings) {
      await initGovernanceSettings();
      return lockProfile(params);
    }

    if (settings.profileLocked) {
      return { success: false, error: `Profile already locked by ${settings.lockedBy}` };
    }

    await db.update(governanceSettings).set({
      profileLocked: true,
      lockedBy: params.actor,
      lockedAt: new Date(),
      lockReason: params.reason,
    }).where(eq(governanceSettings.id, settings.id));

    // Audit log
    await db.insert(governanceAuditLog).values({
      action: 'profile_lock',
      actor: params.actor,
      actorId: params.actorId,
      previousProfile: settings.activeProfile,
      newProfile: settings.activeProfile,
      reason: params.reason,
    });

    dbLog.info({ actor: params.actor, reason: params.reason }, '[GovernanceSettings] Profile LOCKED');
    return { success: true };
  } catch (error) {
    dbLog.error({ err: error instanceof Error ? error : new Error(String(error)) }, '[GovernanceSettings] Error locking profile');
    return { success: false, error: String(error) };
  }
}

/**
 * Unlock the enforcement profile.
 */
export async function unlockProfile(params: {
  actor: string;
  actorId?: number;
  reason: string;
}): Promise<{ success: boolean; error?: string }> {
  const db = await getDb();
  if (!db) return { success: false, error: 'Database not available' };

  try {
    const settings = await getGovernanceSettings();
    if (!settings) return { success: false, error: 'No settings found' };

    if (!settings.profileLocked) {
      return { success: false, error: 'Profile is not locked' };
    }

    await db.update(governanceSettings).set({
      profileLocked: false,
      lockedBy: null,
      lockedAt: null,
      lockReason: null,
    }).where(eq(governanceSettings.id, settings.id));

    // Audit log
    await db.insert(governanceAuditLog).values({
      action: 'profile_unlock',
      actor: params.actor,
      actorId: params.actorId,
      previousProfile: settings.activeProfile,
      newProfile: settings.activeProfile,
      reason: params.reason,
    });

    dbLog.info({ actor: params.actor, reason: params.reason }, '[GovernanceSettings] Profile UNLOCKED');
    return { success: true };
  } catch (error) {
    dbLog.error({ err: error instanceof Error ? error : new Error(String(error)) }, '[GovernanceSettings] Error unlocking profile');
    return { success: false, error: String(error) };
  }
}

