import { ENV } from './_core/env';
import { buildPostgresOptions } from './_core/postgres-options';
import { createHash, randomBytes } from "crypto";
import { unsafeCast } from '../shared/type-bridge';

let _db: ReturnType<typeof drizzle> | null = null;
/** In-flight initialization promise used to prevent thundering-herd reconnection storms. */
let _initPromise: Promise<ReturnType<typeof drizzle>> | null = null;

/** Thrown when the database is configured but unavailable or connection failed. */
export class DatabaseUnavailableError extends Error {
  constructor(message: string) {
    super(message);
    this.name = 'DatabaseUnavailableError';
  }
}

async function createDbConnection(): Promise<ReturnType<typeof drizzle>> {
  if (!ENV.databaseUrl) {
    dbLog.fatal('Missing required env var: DATABASE_URL');
    _db = null;
    _initPromise = null;
    throw new DatabaseUnavailableError('Database configuration is missing or invalid');
  }
  try {
    const client = postgres(
      ENV.databaseUrl,
      buildPostgresOptions({
        databaseUrl: ENV.databaseUrl,
        defaultMax: 5,             // Max connections per machine (2 machines × 5 = 10 total)
        idleTimeout: 30,           // Close idle connections after 30s
        connectTimeout: 10,        // Fail fast if can't connect in 10s
        maxLifetime: 60 * 30,      // Recycle connections every 30 minutes
      }),
    );
    const db = drizzle(client);
    _db = db;
    return db;
  } catch (error) {
    _db = null;
    _initPromise = null;
    const err = error instanceof Error ? error : new Error(String(error));
    // Sanitize error message to prevent DATABASE_URL credentials from leaking into logs.
    // Covers standard URL credential patterns: scheme://user:pass@host and scheme://:pass@host
    const sanitizedMessage = err.message
      .replace(/:\/\/([^:@\/]*):([^@\/]+)@/g, '://[REDACTED]:[REDACTED]@')
      .replace(/:\/\/([^@\/]+)@/g, '://[REDACTED]@');
    const sanitizedErr = Object.assign(new Error(sanitizedMessage), { name: err.name });
    dbLog.error({ err: sanitizedErr }, '[Database] Failed to connect to DATABASE_URL — connection error, not a missing config');
    // Re-throw a structured error so callers can distinguish a misconfigured/failed
    // connection from a deliberately unconfigured database (no DATABASE_URL).
    // Do NOT include err.message in the thrown error to avoid leaking connection details.
    throw new DatabaseUnavailableError('Database connection failed');
  }
}

export async function getDb() {
  if (_db) return _db;
  if (!ENV.databaseUrl) return null;
  // Serialize concurrent initialization attempts to avoid thundering herd.
  if (!_initPromise) {
    _initPromise = createDbConnection().finally(() => {
      _initPromise = null;
    });
  }
  return _initPromise;
}

/** End postgres-js pool (Drizzle stores client on `$client`). Safe to call once at shutdown. */
export async function closeDatabaseConnection(): Promise<void> {
  if (!_db) return;
  try {
    const client = (_db as { $client?: { end: (opts?: { timeout?: number }) => Promise<void> } }).$client;
    if (client?.end) {
      await client.end({ timeout: 5000 });
    }
  } finally {
    _db = null;
    _initPromise = null;
  }
}

/** Drizzle transaction handle type — use as parameter type in withTransaction callbacks */
export type DbTransaction = Parameters<Parameters<Exclude<Awaited<ReturnType<typeof getDb>>, null>['transaction']>[0]>[0];

/**
 * Execute a callback within a database transaction.
 * If the callback throws, the transaction is rolled back automatically.
 * Uses Drizzle's built-in transaction support.
 */
export async function withTransaction<T>(fn: (tx: DbTransaction) => Promise<T>): Promise<T> {
  const db = await getDb();
  if (!db) {
    throw new DatabaseUnavailableError('Database unavailable: cannot start transaction');
  }
  return db.transaction(fn);
}

// ============ User Functions ============

export async function upsertUser(user: InsertUser): Promise<void> {
  if (!user.openId) {
    throw new Error("User openId is required for upsert");
  }

  const db = await getDb();
  if (!db) {
    dbLog.error({}, '[Database] Cannot upsert user: database not available');
    throw new Error('Database unavailable: cannot upsert user');
  }

  try {
    const values: InsertUser = {
      openId: user.openId,
    };
    const updateSet: Record<string, unknown> = {};

    const textFields = ["name", "email", "loginMethod", "passwordHash"] as const;
    type TextField = (typeof textFields)[number];

    const assignNullable = (field: TextField) => {
      const value = user[field];
      if (value === undefined) return;
      const normalized = value ?? null;
      values[field] = normalized;
      updateSet[field] = normalized;
    };

    textFields.forEach(assignNullable);

    if (user.lastSignedIn !== undefined) {
      values.lastSignedIn = user.lastSignedIn;
      updateSet.lastSignedIn = user.lastSignedIn;
    }
    if (user.role !== undefined) {
      values.role = user.role;
      updateSet.role = user.role;
    } else if (user.openId === ENV.ownerOpenId) {
      values.role = 'admin';
      updateSet.role = 'admin';
    }

    if (!values.lastSignedIn) {
      values.lastSignedIn = new Date();
    }

    if (Object.keys(updateSet).length === 0) {
      updateSet.lastSignedIn = new Date();
    }

    await db.insert(users).values(values).onConflictDoUpdate({
      target: users.openId,
      set: updateSet,
    });
  } catch (error) {
    dbLog.error({ err: error instanceof Error ? error : new Error(String(error)) }, '[Database] Failed to upsert user');
    throw error;
  }
}

