/**
 * Get usage breakdown grouped by endpoint for the given user.
 * Returns an array of { tool, calls, percentage } sorted by calls desc.
 */
export async function getUsageBreakdownByEndpoint(userId: number, days: number = 30) {
  const db = await getDb();
  if (!db) return [];

  const startDate = new Date();
  startDate.setDate(startDate.getDate() - days);

  const rows = await db.select({
    endpoint: apiUsage.endpoint,
    totalCalls: sql<number>`SUM(${apiUsage.callCount})`,
  })
    .from(apiUsage)
    .where(and(
      eq(apiUsage.userId, userId),
      sql`${apiUsage.date} >= ${startDate}`
    ))
    .groupBy(apiUsage.endpoint)
    .orderBy(desc(sql`SUM(${apiUsage.callCount})`));

  const grandTotal = rows.reduce((sum, r) => sum + (r.totalCalls || 0), 0) || 1;

  return rows.map(r => ({
    tool: formatEndpointName(r.endpoint),
    calls: r.totalCalls || 0,
    percentage: Math.round(((r.totalCalls || 0) / grandTotal) * 100),
  }));
}

/** Convert endpoint slugs like "content_review" to "Content Review" */
function formatEndpointName(endpoint: string): string {
  return endpoint
    .replace(/[_-]/g, ' ')
    .replace(/\b\w/g, c => c.toUpperCase());
}

