export async function getFailureModeReport(): Promise<{
  topConfusionPairs: Array<{ pair: string; count: number; signals: string[] }>;
  topPredictedStates: Array<{ state: string; errorCount: number }>;
  topActualStates: Array<{ state: string; missedCount: number }>;
  totalFailures: number;
  newFailures: number;
  resolvedFailures: number;
}> {
  const db = await getDb();
  if (!db) {
    return {
      topConfusionPairs: [],
      topPredictedStates: [],
      topActualStates: [],
      totalFailures: 0,
      newFailures: 0,
      resolvedFailures: 0,
    };
  }

  try {
    // Top confusion pairs
    const topPairs = await db.select()
      .from(failureModes)
      .orderBy(desc(failureModes.occurrenceCount))
      .limit(10);

    const topConfusionPairs = topPairs.map(p => ({
      pair: p.confusionPair,
      count: p.occurrenceCount,
      signals: p.commonSignals ? JSON.parse(p.commonSignals) : [],
    }));

    // Top predicted states (most errors from)
    const predictedResult = await db.select({
      state: failureModes.predictedState,
      errorCount: sql<number>`SUM(${failureModes.occurrenceCount})`
    })
      .from(failureModes)
      .groupBy(failureModes.predictedState)
      .orderBy(sql`SUM(${failureModes.occurrenceCount}) DESC`)
      .limit(5);

    const topPredictedStates = predictedResult.map(r => ({
      state: r.state,
      errorCount: r.errorCount,
    }));

    // Top actual states (most missed)
    const actualResult = await db.select({
      state: failureModes.actualState,
      missedCount: sql<number>`SUM(${failureModes.occurrenceCount})`
    })
      .from(failureModes)
      .groupBy(failureModes.actualState)
      .orderBy(sql`SUM(${failureModes.occurrenceCount}) DESC`)
      .limit(5);

    const topActualStates = actualResult.map(r => ({
      state: r.state,
      missedCount: r.missedCount,
    }));

    // Counts
    const totalResult = await db.select({ count: sql<number>`SUM(${failureModes.occurrenceCount})` })
      .from(failureModes);
    const totalFailures = totalResult[0]?.count || 0;

    const newResult = await db.select({ count: sql<number>`SUM(${failureModes.occurrenceCount})` })
      .from(failureModes)
      .where(eq(failureModes.status, 'new'));
    const newFailures = newResult[0]?.count || 0;

    const resolvedResult = await db.select({ count: sql<number>`SUM(${failureModes.occurrenceCount})` })
      .from(failureModes)
      .where(eq(failureModes.status, 'resolved'));
    const resolvedFailures = resolvedResult[0]?.count || 0;

    return {
      topConfusionPairs,
      topPredictedStates,
      topActualStates,
      totalFailures,
      newFailures,
      resolvedFailures,
    };
  } catch (error) {
    dbLog.error({ err: error instanceof Error ? error : new Error(String(error)) }, '[FailureMode] Error generating report');
    return {
      topConfusionPairs: [],
      topPredictedStates: [],
      topActualStates: [],
      totalFailures: 0,
      newFailures: 0,
      resolvedFailures: 0,
    };
  }
}


