    const [inserted] = await db
      .select()
      .from(gravitoReviews)
      .where(eq(gravitoReviews.proofId, review.proofId));

    const decision = review.decision;
    if (decision === "passed" || decision === "blocked" || decision === "warned") {
      await updateGravitoDailyStats(review.userId, decision);
    }

    return inserted || null;
  } catch (error) {
    dbLog.error({ err: error instanceof Error ? error : new Error(String(error)) }, '[GravitoReview] Error recording review');
    return null;
  }
}

export async function updateGravitoDailyStats(
  userId: number, 
  decision: "passed" | "blocked" | "warned"
): Promise<void> {
  const db = await getDb();
  if (!db) return;

  try {
    const today = new Date();
    today.setHours(0, 0, 0, 0);

    // Try to find existing stats for today
    const [existing] = await db
      .select()
      .from(gravitoUsageStats)
      .where(
        and(
          eq(gravitoUsageStats.userId, userId),
          sql`DATE(${gravitoUsageStats.date}) = DATE(${today})`
        )
      );

    if (existing) {
      // Update existing stats - use raw SQL for conditional increments
      const updateFields: Record<string, unknown> = {
        reviewsCount: sql`${gravitoUsageStats.reviewsCount} + 1`,
        proofsGenerated: sql`${gravitoUsageStats.proofsGenerated} + 1`,
      };

      if (decision === "passed") {
        updateFields.passedCount = sql`${gravitoUsageStats.passedCount} + 1`;
      }
      if (decision === "blocked") {
        updateFields.blockedCount = sql`${gravitoUsageStats.blockedCount} + 1`;
      }
      if (decision === "warned") {
        updateFields.warnedCount = sql`${gravitoUsageStats.warnedCount} + 1`;
      }

      await db
        .update(gravitoUsageStats)
        .set(updateFields)
        .where(eq(gravitoUsageStats.id, existing.id));
    } else {
      // Create new stats for today
      await db.insert(gravitoUsageStats).values({
        userId,
        date: today,
        reviewsCount: 1,
        passedCount: decision === "passed" ? 1 : 0,
        blockedCount: decision === "blocked" ? 1 : 0,
        warnedCount: decision === "warned" ? 1 : 0,
        proofsGenerated: 1,
      });
    }
  } catch (error) {
    dbLog.error({ err: error instanceof Error ? error : new Error(String(error)) }, '[GravitoStats] Error updating daily stats');
  }
}

export async function getGravitoStats(userId: number, days: number = 30): Promise<{
  total: number;
  passed: number;
  blocked: number;
  warned: number;
  proofsGenerated: number;
  artifactsReviewed: number;
  gatesBlocked: number;
  lastRunAt: string | null;
