/**
 * Generate pilot weekly report data
 */
export async function generatePilotWeeklyReportData(pilotId: number, weekNumber: number): Promise<{
  proofsGenerated: number;
  artifactsReviewed: number;
  gatesBlocked: number;
  gatesPassed: number;
  experimentsRun: number;
  deltaMeasured: number | null;
}> {
  const db = await getDb();
  if (!db) throw new Error('Database not available');

  // Get pilot
  const pilot = await getPilotById(pilotId);
  if (!pilot) throw new Error('Pilot not found');

  // Calculate week dates
  const pilotCreatedAt = new Date(pilot.createdAt);
  const weekStart = new Date(pilotCreatedAt);
  weekStart.setDate(weekStart.getDate() + (weekNumber - 1) * 7);
  const weekEnd = new Date(weekStart);
  weekEnd.setDate(weekEnd.getDate() + 7);

  // Get proof blocks for this week
  const proofBlocks = await db.select().from(pilotProofBlocks)
    .where(and(
      eq(pilotProofBlocks.pilotId, pilotId),
      sql`${pilotProofBlocks.createdAt} >= ${weekStart}`,
      sql`${pilotProofBlocks.createdAt} < ${weekEnd}`
    ));

  // Get experiments for this week
  const experiments = await db.select().from(pilotExperiments)
    .where(and(
      eq(pilotExperiments.pilotId, pilotId),
      sql`${pilotExperiments.createdAt} >= ${weekStart}`,
      sql`${pilotExperiments.createdAt} < ${weekEnd}`
    ));

  // Calculate delta from completed experiments
  const completedExperiments = experiments.filter((e: PilotExperiment) => e.status === 'completed' && e.delta !== null);
  const avgDelta = completedExperiments.length > 0
    ? Math.round(completedExperiments.reduce((sum: number, e: PilotExperiment) => sum + (e.delta || 0), 0) / completedExperiments.length)
    : null;

  return {
    proofsGenerated: proofBlocks.length,
    artifactsReviewed: proofBlocks.length, // Each proof block = 1 artifact reviewed
    gatesBlocked: proofBlocks.filter((p: PilotProofBlock) => !p.passed).length,
    gatesPassed: proofBlocks.filter((p: PilotProofBlock) => p.passed).length,
    experimentsRun: experiments.length,
    deltaMeasured: avgDelta,
  };
}


