// ============ Confidence Threshold Functions ============

export interface ConfidenceThresholds {
  global: number;
  perDomain: Record<string, number>;
}

const DEFAULT_CONFIDENCE_THRESHOLDS: ConfidenceThresholds = {
  global: 80,
  perDomain: {},
};

/**
 * Get the current confidence thresholds.
 * Returns defaults if none are configured.
 */
export async function getConfidenceThresholds(): Promise<ConfidenceThresholds> {
  try {
    const settings = await getGovernanceSettings();
    if (settings?.confidenceThresholds) {
      return settings.confidenceThresholds;
    }
    return DEFAULT_CONFIDENCE_THRESHOLDS;
  } catch (error) {
    dbLog.error({ err: error instanceof Error ? error : new Error(String(error)) }, '[ConfidenceThresholds] Error reading thresholds');
    return DEFAULT_CONFIDENCE_THRESHOLDS;
  }
}

/**
 * Update confidence thresholds.
 * Validates that global is 0-100 and per-domain values are 0-100.
 */
export async function updateConfidenceThresholds(params: {
  global?: number;
  perDomain?: Record<string, number>;
  actor: string;
}): Promise<{ success: boolean; thresholds: ConfidenceThresholds; error?: string }> {
  const db = await getDb();
  if (!db) return { success: false, thresholds: DEFAULT_CONFIDENCE_THRESHOLDS, error: 'Database not available' };

  try {
    const current = await getConfidenceThresholds();

    // Merge updates
    const updated: ConfidenceThresholds = {
      global: params.global !== undefined ? Math.max(0, Math.min(100, params.global)) : current.global,
      perDomain: params.perDomain !== undefined
        ? Object.fromEntries(
            Object.entries({ ...current.perDomain, ...params.perDomain })
              .map(([k, v]) => [k, Math.max(0, Math.min(100, v))])
              .filter(([_, v]) => v !== undefined)
          )
        : current.perDomain,
    };

    const settings = await getGovernanceSettings();
    if (!settings) {
      await initGovernanceSettings();
      return updateConfidenceThresholds(params);
    }

    await db.update(governanceSettings).set({
      confidenceThresholds: updated,
      lastUpdatedBy: params.actor,
      lastUpdatedAt: new Date(),
    }).where(eq(governanceSettings.id, settings.id));

    dbLog.info({ actor: params.actor, global: updated.global, perDomain: updated.perDomain }, '[ConfidenceThresholds] Updated');

    return { success: true, thresholds: updated };
  } catch (error) {
    dbLog.error({ err: error instanceof Error ? error : new Error(String(error)) }, '[ConfidenceThresholds] Error updating thresholds');
    return { success: false, thresholds: DEFAULT_CONFIDENCE_THRESHOLDS, error: String(error) };
  }
}

/**
 * Get the effective threshold for a specific domain.
 * Uses per-domain override if set, otherwise falls back to global.
 */
export function getEffectiveThreshold(thresholds: ConfidenceThresholds, domain: string): number {
  return thresholds.perDomain[domain] ?? thresholds.global;
}

// ============ MCP Usage Per-Key Functions ============

export async function getUsageByApiKeyPrefix(keyPrefix: string, days: number = 30) {
  const db = await getDb();
  if (!db) return { totalCalls: 0, successRate: 0, topTools: [], dailyBreakdown: [] };
  try {
    const since = new Date();
    since.setDate(since.getDate() - days);

    const logs = await db.select()
      .from(mcpUsageLog)
      .where(and(
        like(mcpUsageLog.apiKey, `${keyPrefix}%`),
        gte(mcpUsageLog.createdAt, since)
      ))
      .orderBy(desc(mcpUsageLog.createdAt))
      .limit(10000);

    const totalCalls = logs.length;
    const successCount = logs.filter(l => l.success).length;
    const successRate = totalCalls > 0 ? Math.round((successCount / totalCalls) * 100) : 0;

    // Top tools by frequency
    const toolCounts: Record<string, number> = {};
    for (const log of logs) {
      toolCounts[log.toolName] = (toolCounts[log.toolName] || 0) + 1;
    }
    const topTools = Object.entries(toolCounts)
      .sort((a, b) => b[1] - a[1])
      .slice(0, 10)
      .map(([name, count]) => ({ name, count }));

    // Daily breakdown
    const dailyMap: Record<string, { calls: number; success: number }> = {};
    for (const log of logs) {
      const day = new Date(log.createdAt).toISOString().split('T')[0];
      if (!dailyMap[day]) dailyMap[day] = { calls: 0, success: 0 };
      dailyMap[day].calls++;
      if (log.success) dailyMap[day].success++;
    }
    const dailyBreakdown = Object.entries(dailyMap)
      .sort((a, b) => a[0].localeCompare(b[0]))
      .map(([date, data]) => ({ date, ...data }));

    // Average response time
    const responseTimes = logs.filter(l => l.responseTimeMs != null).map(l => l.responseTimeMs!);
    const avgResponseTime = responseTimes.length > 0
      ? Math.round(responseTimes.reduce((a, b) => a + b, 0) / responseTimes.length)
      : 0;

    return { totalCalls, successRate, topTools, dailyBreakdown, avgResponseTime };
  } catch (error) {
    dbLog.error({ err: error instanceof Error ? error : new Error(String(error)) }, '[MCP Usage] Error querying per-key usage');
    return { totalCalls: 0, successRate: 0, topTools: [], dailyBreakdown: [], avgResponseTime: 0 };
  }
}


/**
 * Update rate limit override for a specific API key.
 * null = use plan default, -1 = unlimited, positive int = custom req/min
 */
export async function updateApiKeyRateLimit(
  userId: number,
  keyId: number,
  rateLimitOverride: number | null
): Promise<void> {
  const database = await getDb();
  if (!database) throw new Error("Database not available");
  const updated = await database
    .update(apiKeys)
    .set({ rateLimitOverride })
    .where(and(eq(apiKeys.id, keyId), eq(apiKeys.userId, userId)))
    .returning({ id: apiKeys.id });

  if (updated.length === 0) {
    throw new Error("API key not found or not owned by user");
  }
}


