/**
 * Get entitlement denial history for a specific org (tenant-scoped).
 */
export async function getEntitlementDenialsByOrg(orgId: number, limit: number = 100) {
  const db = await getDb();
  if (!db) return [];
  try {
    return await db
      .select()
      .from(entitlementDenials)
      .where(eq(entitlementDenials.orgId, orgId))
      .orderBy(desc(entitlementDenials.createdAt))
      .limit(limit);
  } catch (error) {
    dbLog.error({ err: error instanceof Error ? error : new Error(String(error)) }, '[TenantScope] Error getting denials for org');
    return [];
  }
}

/**
 * Get entitlement denial summary for a specific org (tenant-scoped).
 */
export async function getEntitlementDenialSummaryByOrg(orgId: number, days: number = 30) {
  const db = await getDb();
  if (!db) return { total: 0, byReason: {}, byProduct: {} };
  try {
    const since = new Date();
    since.setDate(since.getDate() - days);

    const denials = await db
      .select()
      .from(entitlementDenials)
      .where(
        and(
          eq(entitlementDenials.orgId, orgId),
          gte(entitlementDenials.createdAt, since)
        )
      )
      .orderBy(desc(entitlementDenials.createdAt));

    const byReason: Record<string, number> = {};
    const byProduct: Record<string, number> = {};
    for (const d of denials) {
      byReason[d.reason] = (byReason[d.reason] || 0) + 1;
      byProduct[d.productCode] = (byProduct[d.productCode] || 0) + 1;
    }

    return { total: denials.length, byReason, byProduct };
  } catch (error) {
    dbLog.error({ err: error instanceof Error ? error : new Error(String(error)) }, '[TenantScope] Error getting denial summary');
    return { total: 0, byReason: {}, byProduct: {} };
  }
}

