/**
 * Get MCP usage logs scoped to a specific org via API key prefix lookup.
 */
export async function getMcpUsageByOrg(orgId: number, days: number = 30) {
  const db = await getDb();
  if (!db) return { totalCalls: 0, successRate: 0, topTools: [], dailyBreakdown: [] };
  try {
    // First, get all API key prefixes for this org
    const orgKeys = await db
      .select({ keyPrefix: apiKeys.keyPrefix })
      .from(apiKeys)
      .where(eq(apiKeys.orgId, orgId));

    if (orgKeys.length === 0) {
      return { totalCalls: 0, successRate: 0, topTools: [], dailyBreakdown: [] };
    }

    const since = new Date();
    since.setDate(since.getDate() - days);

    // Get usage for all org keys
    const keyPrefixes = orgKeys.map(k => k.keyPrefix);
    const logs = await db
      .select()
      .from(mcpUsageLog)
      .where(
        and(
          sql`${mcpUsageLog.apiKey} IN (${sql.join(keyPrefixes.map(p => sql`${p}`), sql`, `)})`,
          gte(mcpUsageLog.createdAt, since)
        )
      )
      .orderBy(desc(mcpUsageLog.createdAt))
      .limit(10000);

    const totalCalls = logs.length;
    const successCount = logs.filter(l => l.success).length;
    const successRate = totalCalls > 0 ? Math.round((successCount / totalCalls) * 100) : 0;

    const toolCounts: Record<string, number> = {};
    for (const log of logs) {
      toolCounts[log.toolName] = (toolCounts[log.toolName] || 0) + 1;
    }
    const topTools = Object.entries(toolCounts)
      .sort((a, b) => b[1] - a[1])
      .slice(0, 10)
      .map(([name, count]) => ({ name, count }));

    const dailyMap: Record<string, { calls: number; success: number }> = {};
    for (const log of logs) {
      const day = new Date(log.createdAt).toISOString().split('T')[0];
      if (!dailyMap[day]) dailyMap[day] = { calls: 0, success: 0 };
      dailyMap[day].calls++;
      if (log.success) dailyMap[day].success++;
    }
    const dailyBreakdown = Object.entries(dailyMap)
      .sort((a, b) => a[0].localeCompare(b[0]))
      .map(([date, data]) => ({ date, ...data }));

    return { totalCalls, successRate, topTools, dailyBreakdown };
  } catch (error) {
    dbLog.error({ err: error instanceof Error ? error : new Error(String(error)) }, '[TenantScope] Error getting MCP usage for org');
    return { totalCalls: 0, successRate: 0, topTools: [], dailyBreakdown: [] };
  }
}


